internal static class AiSceneEquipment {
 sealed class Job {internal LiveActorReference Actor=null!;internal ItemAttachmentNode Tree=null!;internal EquipmentSlot Slot;internal bool Started,Ready,Paused,Committed,DrawDone,EquipNow=true,NeedsEmpty,DirectEmpty;internal IntPtr OriginalPointer;internal string OriginalId="",PresetName="";internal float Since;internal string Error="";internal Callback<IEmptyHandsController>? Empty;internal Callback<IFirearmHandsController>? Draw;}
 static readonly Queue<Job> queue=new();static Job? active;static ConfigEntry<bool> birth=null!;static ConfigEntry<string> weapon=null!;static string search="",notice="";static Vector2 scroll;static int slotChoice;static bool equipNow=true;static string chosenPreset="";
 internal static void Initialize(){birth=FeatureConfig.Bind("49. AI 动作导演","Birth player weapon","出生使用玩家枪械预设",false);weapon=FeatureConfig.Bind("49. AI 动作导演","Birth weapon tree","出生枪械预设数据","");}
 internal static bool Busy=>active!=null||queue.Count>0;
 internal static void ResumeAfterEquip(Player actor){if(active?.Actor.Pointer==actor.Pointer&&active.Actor.Profile==actor.ProfileId)active.Paused=false;}
 internal static ItemAttachmentNode? BirthWeapon=>birth.Value&&weapon.Value.Length>0?JsonSerializer.Deserialize<ItemAttachmentNode>(weapon.Value):null;
 internal static ItemAttachmentNode? ToolWeapon=>weapon.Value.Length>0?JsonSerializer.Deserialize<ItemAttachmentNode>(weapon.Value):null;
 internal static void LoadBirth(ItemAttachmentNode? tree){weapon.Value=tree==null?"":JsonSerializer.Serialize(tree);birth.Value=tree!=null;}
 internal static ItemAttachmentNode Clone(ItemAttachmentNode tree)=>JsonSerializer.Deserialize<ItemAttachmentNode>(JsonSerializer.Serialize(tree))!;
 static Weapon Build(ItemAttachmentNode tree){var factory=Singleton<ItemFactory>.Instance??throw new ArgumentException("物品工厂未就绪。");var item=factory.CreateItem(factory.NextId.ToString(),tree.Template,null)?.TryCast<Weapon>()??throw new ArgumentException("预设不是枪械。");tree.Parameters.Apply(item);ItemAttachments.Apply(item,factory,tree);return item;}
 internal static Dictionary<string,ItemAttachmentNode?> Capture(Player actor){var result=new Dictionary<string,ItemAttachmentNode?>();var slots=actor.Profile?.Inventory?.Equipment?.Slots;if(slots!=null)foreach(var slot in slots)if(slot!=null)result[slot.ID]=slot.ContainedItem is {} item?LoadoutPlans.CaptureItem(item):null;return result;}
 internal static void Prepare(Profile profile,AiBirthPreset preset){
  var equipment=profile.Inventory?.Equipment;var factory=Singleton<ItemFactory>.Instance;if(equipment==null||factory==null)return;
  if(preset.Equipment!=null)foreach(var pair in preset.Equipment){if(!Enum.TryParse<EquipmentSlot>(pair.Key,out var type))continue;var target=equipment.GetSlot(type);if(target==null)continue;var tree=pair.Value;Item? item=null;if(tree!=null){item=factory.CreateItem(factory.NextId.ToString(),tree.Template,null);tree.Parameters.Apply(item);ItemAttachments.Apply(item,factory,tree);}if(target.ContainedItem!=null&&!target.RemoveItemWithoutRestrictions().Succeeded)throw new ArgumentException("无法还原装备槽："+pair.Key);if(item!=null&&!target.AddWithoutRestrictions(item).Succeeded)throw new ArgumentException("装备槽还原失败："+pair.Key);}
  if(preset.Weapon!=null){var gun=Build(preset.Weapon);var target=equipment.GetSlot(EquipmentSlot.FirstPrimaryWeapon);if(target.ContainedItem!=null&&!target.RemoveItemWithoutRestrictions().Succeeded)throw new ArgumentException("无法替换出生主武器。");if(!target.Add(gun,false,true).Succeeded)throw new ArgumentException("出生枪械无法放入主武器槽。");}
  if(preset.Appearance!=null){var custom=new BodyCustomization();foreach(var pair in preset.Appearance)custom[Enum.Parse<EBodyModelPart>(pair.Key)]=new MongoID(pair.Value);profile.Customization=custom;}
  if(!string.IsNullOrWhiteSpace(preset.Name))profile.Info.Nickname=preset.Name;
 }
 internal static void Enqueue(GameWorld current,Player actor,ItemAttachmentNode tree,EquipmentSlot target=EquipmentSlot.FirstPrimaryWeapon,bool draw=true,string presetName=""){if(AiEquipmentRemoval.Busy)throw new ArgumentException("正在删除 AI 装备，请稍候。");if(queue.Count+(active==null?0:1)>=64)throw new ArgumentException("装备队列已满。");new LiveActorReference(current,actor).Resolve();if(actor.IsYourPlayer||!(actor.IsAI||actor.AIData?.BotOwner!=null)||!AiWeaponSlotRules.Allowed(target.ToString()))throw new ArgumentException("请选择 AI 的枪械槽位。");var old=actor.Profile?.Inventory?.Equipment?.GetSlot(target)?.ContainedItem;queue.Enqueue(new(){Actor=new(current,actor),Tree=Clone(tree),Slot=target,EquipNow=draw,OriginalId=old?.Id??"",OriginalPointer=old?.Pointer??IntPtr.Zero,PresetName=presetName});notice="已加入 AI 换枪队列。";}
 static void Finish(){if(active?.Started==true)try{AiTestControl.SetPaused(new[]{active.Actor.Resolve()},active.Paused);}catch{}active=null;}
 internal static void Reset(){Finish();queue.Clear();}
 internal static void Tick(GameWorld? current){if(current==null){Reset();return;}if(active==null&&queue.Count>0)active=queue.Dequeue();var job=active;if(job==null)return;
  try{var actor=job.Actor.Resolve();if(job.Committed){if(job.DrawDone||Time.unscaledTime-job.Since>20)Finish();return;}if(!job.Started){job.Started=true;job.Since=Time.unscaledTime;job.Paused=AiTestControl.IsPaused(actor);var old=actor.Profile.Inventory.Equipment.GetSlot(job.Slot).ContainedItem;if((old?.Pointer??IntPtr.Zero)!=job.OriginalPointer||(old?.Id??"")!=job.OriginalId)throw new ArgumentException("目标槽武器已改变，请重新提交换枪，未移除新的装备。");AiTestControl.SetPaused(new[]{actor},true);job.NeedsEmpty=actor.HandsController?.Item!=null&&(job.EquipNow||actor.HandsController.Item.Pointer==old?.Pointer);if(job.NeedsEmpty){job.Empty=(Action<Result<IEmptyHandsController>>)(result=>{if(!ReferenceEquals(active,job))return;job.Ready=true;job.Error=result.Succeed?"":result.Error??"AI 收起武器失败。";});actor.HandsController?.TryCast<Player.FirearmController>()?.SetTriggerPressed(false);AiHandsTransition.Empty(actor,job.Empty);}else job.Ready=true;}
   if(Time.unscaledTime-job.Since>20)throw new ArgumentException("AI 收起武器超时。");if(job.Ready&&job.Error.Length>0&&!job.DirectEmpty){job.DirectEmpty=true;job.Ready=false;job.Error="";AiHandsTransition.Empty(actor,job.Empty!,true);}if(!job.Ready)return;if(job.Error.Length>0)throw new ArgumentException(job.Error);if(job.NeedsEmpty&&actor.HandsController?.Item!=null)return;
   var target=actor.Profile.Inventory.Equipment.GetSlot(job.Slot);var oldItem=target.ContainedItem;if((oldItem?.Pointer??IntPtr.Zero)!=job.OriginalPointer||(oldItem?.Id??"")!=job.OriginalId)throw new ArgumentException("收枪期间目标装备已改变，未删除新的武器。");if(oldItem!=null&&actor.HandsController?.Item?.Pointer==oldItem.Pointer)return;
   var gun=Build(job.Tree);var controller=actor.InventoryController;var address=target.CreateItemAddress();
   if(oldItem!=null){var removed=ItemManipulator.RemoveWithoutRestrictions(oldItem,controller);if(!removed.Succeeded)throw new ArgumentException("旧武器未能移除。");removed.Value.RaiseEvents(controller.Cast<IItemOwner>(),CommandStatus.Succeed);}
   var added=ItemManipulator.Add(gun,address,controller,true);if(!added.Succeeded){if(oldItem!=null){ItemManipulator.Add(oldItem,address,controller,true);controller.AddAndRaiseEvents(oldItem,address);}throw new ArgumentException("预设枪械无法装备，已尝试恢复旧武器。");}controller.AddAndRaiseEvents(gun,address);if(target.ContainedItem?.Pointer!=gun.Pointer)throw new ArgumentException("新武器未能绑定到目标槽位。");job.Committed=true;if(oldItem!=null){AiEquipmentEditor.ForgetRemoved(oldItem);WeaponEditor.ForgetRemoved(oldItem);}actor.RecalculateEquipmentParams();actor.Physical?.MarkWeightAsDirty();actor.AIData?.BotOwner?.WeaponManager?.UpdateWeaponsList();actor.AIData?.BotOwner?.WeaponManager?.Selector?.FindItemsInSlots(true);actor.AIData?.BotOwner?.WeaponManager?.Selector?.UpdateWeaponsList();
   notice="已给 "+actor.Profile.Nickname+" 换上 "+(job.PresetName.Length>0?job.PresetName:ItemSpawner.TemplateName(job.Tree.Template))+"。";if(!job.EquipNow){job.DrawDone=true;FeatureToasts.Show(notice);Finish();return;}job.Committed=true;job.Since=Time.unscaledTime;job.Draw=(Action<Result<IFirearmHandsController>>)(result=>{if(!ReferenceEquals(active,job))return;job.DrawDone=true;if(!result.Succeed){notice="武器已装备，但持枪切换失败："+result.Error;Plugin.Self.Log.LogWarning("AI equip draw: "+result.Error);}FeatureToasts.Show(notice);});actor.Proceed(gun,job.Draw,true);
  }catch(Exception e){notice=(job.Committed?"新武器已装备，后续处理提示：":"换枪失败：")+e.Message;FeatureToasts.Show(notice);Plugin.Self.Log.LogWarning("AI scene equipment: "+notice);Finish();}}
 static string HeldSlot(Player actor){var held=actor.HandsController?.Item;if(held!=null)foreach(string slot in AiWeaponSlotRules.Slots)if(actor.Profile?.Inventory?.Equipment?.GetSlot(Enum.Parse<EquipmentSlot>(slot))?.ContainedItem?.Pointer==held.Pointer)return slot;return "";}
 static void EquipSelected(string presetId,string presetName){try{var current=Singleton<GameWorld>.Instance??throw new ArgumentException("请进入战局。");var selected=AiTestControl.CheckedSelection;if(selected.Length==0)throw new ArgumentException("请先在 AI 列表勾选要换枪的 AI。");var tree=PlayerWeaponPresets.SceneWeapon(presetId);var result=BuffBatch.Run(selected,p=>p.Profile?.Nickname??"AI",actor=>Enqueue(current,actor,tree,Enum.Parse<EquipmentSlot>(AiWeaponSlotRules.Resolve(slotChoice,HeldSlot(actor))),equipNow,presetName));notice=$"换枪预设“{presetName}”：已排队 {result.Succeeded}/{result.Total} 名 AI。";if(result.Failures.Length>0)notice+=" "+string.Join("；",result.Failures.Take(2));FeatureToasts.Show(notice);}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);}}
 internal static void Draw(Rect rect){
  float x=rect.x,y=rect.y,w=rect.width;InterfaceMenu.Label(new Rect(x,y,w-150,30),"给 AI 换武器 · 导入玩家改枪预设",InterfaceMenu.Accent,19);
