  var slots=new[]{"当前手持","第一主武器","第二主武器","手枪"};float cell=(w-24)/4;for(int i=0;i<slots.Length;i++)if(InterfaceMenu.Button(new Rect(x+i*(cell+8),y,cell,32),slots[i],slotChoice==i))slotChoice=i;y+=42;
  if(InterfaceMenu.Button(new Rect(x,y,w,30),equipNow?"换枪后立即持枪 · 开":"只替换装备槽 · 关",equipNow))equipNow=!equipNow;y+=42;search=InterfaceMenu.Field(new Rect(x,y,w,30),search);if(search.Length==0)InterfaceMenu.Label(new Rect(x+12,y,w-24,30),"搜索玩家预设名称…",Color.Lerp(InterfaceMenu.Text,InterfaceMenu.Background,.5f),12);y+=42;
  (string Id,string Name)[] entries;try{entries=PlayerWeaponPresets.SceneEntries().Where(e=>e.Name.Contains(search,StringComparison.OrdinalIgnoreCase)).ToArray();}catch(Exception e){entries=Array.Empty<(string,string)>();notice=e.Message;}
  var area=new Rect(x,y,w,Math.Max(50,rect.yMax-y-128));scroll=GUI.BeginScrollView(area,scroll,new Rect(0,0,w-22,Math.Max(area.height-1,entries.Length*100)));var picked=AiTestControl.CheckedSelection;int first=Math.Max(0,(int)(scroll.y/100)),end=Math.Min(entries.Length,first+(int)Math.Ceiling(area.height/100)+1);
  for(int i=first;i<end;i++){var entry=entries[i];float top=i*100;InterfaceMenu.Surface(new Rect(2,top,w-30,92),Color.Lerp(InterfaceMenu.Background,InterfaceMenu.Accent,chosenPreset==entry.Id ? .1f : .025f),8);InterfaceMenu.Label(new Rect(14,top+6,w-52,26),entry.Name,InterfaceMenu.Text,14);float half=(w-56)/2;bool old=GUI.enabled;GUI.enabled=old&&picked.Length>0&&!AiEquipmentRemoval.Busy&&queue.Count<64;if(InterfaceMenu.Button(new Rect(14,top+44,half,32),"给所选 AI 换上（"+picked.Length+"）")){chosenPreset=entry.Id;EquipSelected(entry.Id,entry.Name);}GUI.enabled=old;if(InterfaceMenu.Button(new Rect(24+half,top+44,half,32),"导入到出生／玩具枪"))try{weapon.Value=JsonSerializer.Serialize(PlayerWeaponPresets.SceneWeapon(entry.Id));birth.Value=true;chosenPreset=entry.Id;notice="已导入出生／玩具枪预设："+entry.Name;FeatureToasts.Show(notice);}catch(Exception e){notice=e.Message;}}
  if(entries.Length==0)InterfaceMenu.Paragraph(new Rect(10,12,w-48,74),search.Length>0?"没有匹配的预设。":"没有读取到玩家预设。先在游戏改枪界面保存方案，再点击右上角刷新。",null,13);GUI.EndScrollView();
  float footer=rect.yMax-114;InterfaceMenu.Paragraph(new Rect(x,footer,w,42),notice+(Busy?"\n换枪队列："+(queue.Count+(active==null?0:1))+" 名 AI":""),InterfaceMenu.Accent,12);if(InterfaceMenu.Button(new Rect(x,footer+54,w,30),birth.Value?"出生／模板使用已导入枪械 · 开":"出生／模板使用已导入枪械 · 关",birth.Value))birth.Value=!birth.Value;
 }
